WITH filtered AS (SELECT *, REGEXP_EXTRACT(email, '@(.+)$', 1) AS email_domain, DATE_TRUNC('month', hire_date) AS hire_date_period FROM employees WHERE hire_date > DATE '2023-10-02') SELECT *, FIRST_VALUE(job_title) IGNORE NULLS OVER (ORDER BY hire_date_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, SUM(salary) OVER (PARTITION BY level ORDER BY CAST(hire_date_period AS BIGINT) ASC RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS salary_sum_7d, LEAD(salary, 2) OVER (PARTITION BY manager_id ORDER BY hire_date_period ASC, id ASC) AS next_salary FROM filtered;
